:root {
  --cream: #f2ead8;
  --parchment: #e4d5b0;
  --ink: #2c1f0e;
  --ink-mid: #4a3520;
  --ink-light: #7a6248;
  --rust: #a0421d;
  --rust-pale: #e8c4a8;
  --olive: #5a6630;
  --olive-pale: #d4dbb8;
  --slate: #3d4f5c;
  --slate-pale: #c4d0d8;
  --gold: #b8872a;
  --gold-pale: #f0dfa0;
  --border: #c4a86a;
}

.registry-card {
  background-color: var(--cream);
  border: 2px solid var(--border);
  border-radius: 4px;
  width: 480px;
  padding: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.card-header {
  background-color: var(--ink);
  color: var(--cream);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 3px solid var(--gold);
}

.header-emblem {
  font-size: 22px;
  color: var(--gold);
  line-height: 1;
  flex-shrink: 0;
}

.header-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.card-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--gold);
  text-transform: uppercase;
}

.card-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--cream);
  margin: 0;
  line-height: 1.1;
}

.card-number {
  font-size: 13px;
  font-weight: 700;
  color: var(--gold);
  background-color: var(--ink-mid);
  border: 1px solid var(--gold);
  border-radius: 3px;
  padding: 3px 8px;
  flex-shrink: 0;
}

.block-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border-bottom: 1px solid var(--border);
}

.block-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 12px 8px;
  margin: 0;
  border-right: 1px solid var(--border);
  background-color: var(--cream);
  text-align: center;
}

.block-item:last-child {
  border-right: none;
}

.block-item.featured {
  background-color: var(--gold-pale);
}

.block-icon {
  font-size: 24px;
  color: var(--ink-mid);
  line-height: 1;
}

.block-item.featured .block-icon {
  color: var(--rust);
}

.block-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.block-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.2;
}

.block-type {
  font-size: 9px;
  font-weight: 600;
  color: var(--ink-light);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.block-status {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.5px;
  padding: 2px 7px;
  border-radius: 10px;
  text-transform: uppercase;
}

.block-status.active {
  background-color: var(--olive-pale);
  color: var(--olive);
  border: 1px solid var(--olive);
}

.block-status.retired {
  background-color: var(--slate-pale);
  color: var(--slate);
  border: 1px solid var(--slate);
}

.block-status.repair {
  background-color: var(--rust-pale);
  color: var(--rust);
  border: 1px solid var(--rust);
}

.detail-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-bottom: 1px solid var(--border);
  background-color: var(--parchment);
}

.detail-cell {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px 12px;
  border-right: 1px solid var(--border);
}

.detail-cell:last-child {
  border-right: none;
}

.detail-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--ink-light);
}

.detail-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--ink);
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  background-color: var(--ink-mid);
  gap: 10px;
}

.footer-seal {
  font-size: 10px;
  font-weight: 700;
  color: var(--gold);
  letter-spacing: 1.5px;
  flex-shrink: 0;
}

.footer-tags {
  display: flex;
  gap: 5px;
  list-style: none;
  margin: 0;
  padding: 0;
  flex: 1;
  justify-content: center;
}

.tag {
  font-size: 9px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 2px;
  background-color: var(--ink);
  color: var(--rust-pale);
  border: 1px solid var(--rust);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.footer-date {
  font-size: 11px;
  font-weight: 700;
  color: var(--parchment);
  flex-shrink: 0;
}
